text:
{
  "title_novice": "Поправки λ за глину и пористость",
  "summary": [
    {"text": "Измеренное λ зависит не только от нужного свойства, но и от глинистости и пористости, поэтому его надо исправить.", "claims": ["c1", "c2"]},
    {"text": "Поправку за глинистость вычитают из λ по формуле (I.8), где важны декременты глины и чистого скелета.", "claims": ["c1", "c4"]},
    {"text": "Поправку за пористость считают так же, условно считая пласт водоносным, и приводят λ к типичной пористости.", "claims": ["c2", "c3"]}
  ],
  "claims": [
    {"key": "c1", "text": "Поправка за глинистость вычитается из λ; её величину даёт формула (I.8).", "kind": "inference", "unit_id": "u-029-3970ae", "page": 29, "quote": "Исправление за влияние глинистости сводится к вычитанию из λ величины", "numbers": ["I.8"], "question": null},
    {"key": "c2", "text": "Поправку за пористость определяют так же, как поправку за глинистость, условно считая пласт водоносным (формула I.9).", "kind": "assumption", "unit_id": "u-029-350236", "page": 29, "quote": "Аналогично поправку за влияние пористости (условно считая, что пласт водоносный) определяют по формуле", "numbers": ["I.9"], "question": "q1"},
    {"key": "c3", "text": "Типичное значение пористости выбирают произвольно; к нему приводят значения λ.", "kind": "assumption", "unit_id": "u-029-c1f956", "page": 29, "quote": "некоторое произвольное, но типичное значение  \\( K_{н} \\) , к которому «приводятся» значения  \\( \\lambda \\) .", "numbers": [], "question": null},
    {"key": "c4", "text": "λ_гл относится к глинистой фракции, λ_гв — к чистому скелету, λ_в — к пластовой воде.", "kind": "inference", "unit_id": "u-029-c1f956", "page": 29, "quote": "декремент затухания в глинистой фракции, чистом скелете и пластовой воде", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Глинистость и пористость влияют на измеренное λ. Поэтому в сравнении пластов их вклад нужно учесть.", "claims": ["c1", "c2"], "hypothesis": false},
    {"text": "По формуле (I.8) поправка за глинистость равна коэффициенту глинистости, умноженному на разность λ_гл и λ_гв.", "claims": ["c1", "c4"], "hypothesis": false},
    {"text": "Почему декременты глины, скелета и воды различаются, в узле не объясняется. Гипотеза: причина — разное замедление и поглощение нейтронов в этих средах.", "claims": ["c4"], "hypothesis": true},
    {"text": "Поправка за пористость считается по той же схеме, но для условно водоносного пласта. Значения λ приводят к выбранной типичной пористости.", "claims": ["c2", "c3"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист берёт значение λ по пласту, оценивает K_гл и K_п и считает поправки по формулам (I.8) и (I.9).", "claims": ["c1", "c2"], "hypothesis": false},
    {"text": "Специалист выбирает одно типичное K_п0 и приводит к нему значения λ по всем пластам, которые сравнивает.", "claims": ["c3"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Поправка за пористость задана для условно водоносного пласта. Для других флюидов по этому узлу её применять нельзя.", "claims": ["c2"], "hypothesis": false},
    {"text": "Текст не говорит прямо, что поправку за пористость вычитают из λ. Сказано лишь, что её определяют аналогично поправке за глинистость.", "claims": ["c2", "c1"], "hypothesis": false},
    {"text": "Типичное значение K_п0 произвольно. Другой выбор даст другие приведённые значения λ. Поэтому сравнивать можно только при одном K_п0.", "claims": ["c3"], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Зачем условно считать пласт водоносным", "text": "Гипотеза: λ водоносного пласта служит общей опорой. Тогда отклонения от неё удобно считать одной поправкой. В узле причина не разобрана.", "claims": [], "hypothesis": true}
  ],
  "procedure": [
    {"text": "Вычислить поправку за глинистость по формуле (I.8).", "claims": ["c1"]},
    {"text": "Вычесть поправку за глинистость из измеренного λ.", "claims": ["c1"]},
    {"text": "Вычислить поправку за пористость по формуле (I.9), условно считая пласт водоносным.", "claims": ["c2"]},
    {"text": "Привести значения λ к выбранному типичному значению пористости K_п0.", "claims": ["c3"]}
  ],
  "numbers_conditions": [
    {"text": "Поправка за глинистость: Δλ_гл = K_гл(λ_гл − λ_гв), формула (I.8).", "claims": ["c1"]},
    {"text": "Поправка за пористость — по формуле (I.9) только при условии, что пласт считают водоносным.", "claims": ["c2"]},
    {"text": "Типичное значение пористости K_п0 выбирают произвольно.", "claims": ["c3"]}
  ],
  "terms_defined": [
    {"term": "приведение к типичной пористости", "term_en": "normalization to typical porosity", "abbr": "", "definition": "Пересчёт значений λ к одному выбранному типичному значению пористости, чтобы сравнивать пласты между собой.", "claims": ["c3"]},
    {"term": "поправка за глинистость", "term_en": "clay correction", "abbr": "", "definition": "Величина, которую вычитают из измеренного λ, чтобы убрать вклад глинистости. Считается по формуле (I.8).", "claims": ["c1"]},
    {"term": "глинистая фракция", "term_en": "clay fraction", "abbr": "", "definition": "Глинистая часть породы. Для неё задают свой декремент затухания λ_гл.", "claims": ["c4"]},
    {"term": "чистый скелет", "term_en": "clean matrix", "abbr": "", "definition": "Твёрдая основа породы без глинистой части. Для неё задают декремент λ_гв.", "claims": ["c4"]}
  ],
  "terms_used": ["декремент затухания λ", "коэффициент пористости (kп)", "коэффициент глинистости Kгл", "пластовая вода", "водоносный пласт", "нейтронные методы"],
  "formulas": [
    {"unit_id": "u-029-2eb9f2", "label": "(I.8)", "latex": "\\Delta \\lambda_{\\mathrm{гл}} = \\mathrm{K}_{\\mathrm{гл}}(\\lambda_{\\mathrm{гл}} - \\lambda_{\\mathrm{гв}})", "meaning": "Поправка за глинистость, которую вычитают из λ.", "variables": [
      {"symbol": "Δλ_гл", "meaning": "поправка за глинистость", "unit": "не указана в узле"},
      {"symbol": "K_гл", "meaning": "коэффициент глинистости", "unit": "не указана в узле (по смыслу доля)"},
      {"symbol": "λ_гл", "meaning": "декремент затухания в глинистой фракции", "unit": "не указана в узле"},
      {"symbol": "λ_гв", "meaning": "декремент затухания в чистом скелете", "unit": "не указана в узле"}
    ]},
    {"unit_id": "u-029-744f87", "label": "(I.9)", "latex": "\\Delta \\lambda_{\\mathrm{п}} = (\\mathrm{K}_{\\mathrm{п}} - \\mathrm{K}_{\\mathrm{п}0})(\\lambda_{\\mathrm{в}} - \\lambda_{\\mathrm{гв}})", "meaning": "Поправка за отклонение пористости от типичной; считается условно для водоносного пласта.", "variables": [
      {"symbol": "Δλ_п", "meaning": "поправка за пористость", "unit": "не указана в узле"},
      {"symbol": "K_п", "meaning": "коэффициент пористости пласта", "unit": "не указана в узле (по смыслу доля)"},
      {"symbol": "K_п0", "meaning": "типичное значение пористости, выбранное произвольно", "unit": "не указана в узле"},
      {"symbol": "λ_в", "meaning": "декремент затухания в пластовой воде", "unit": "не указана в узле"},
      {"symbol": "λ_гв", "meaning": "декремент затухания в чистом скелете", "unit": "не указана в узле"}
    ]}
  ],
