      {"text": "Оценка коэффициента пористости K_п.", "claims": ["c2"], "hypothesis": false},
      {"text": "Значения λ_гл, λ_гв и λ_в для глины, скелета и воды.", "claims": ["c4"], "hypothesis": false},
      {"text": "Выбранное типичное значение K_п0.", "claims": ["c3"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "λ, уменьшенное на поправку за глинистость (I.8).", "claims": ["c1"], "hypothesis": false},
      {"text": "Поправка за пористость Δλ_п (I.9), для условно водоносного пласта.", "claims": ["c2"], "hypothesis": false},
      {"text": "Значения λ, приведённые к одной типичной пористости K_п0.", "claims": ["c3"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Поправка за пористость верна только при допущении, что пласт водоносный.", "claims": ["c2"], "hypothesis": false},
      {"text": "Без λ_гл, λ_гв и λ_в поправки по формулам вычислить нельзя.", "claims": ["c4"], "hypothesis": false},
      {"text": "Значения, приведённые к разным K_п0, нельзя сравнивать между собой (гипотеза).", "claims": ["c3"], "hypothesis": true}
    ]
  },
